import {BUILDINGS,POLICIES,initialState,metrics,identity,build,decide,advance,continueTerm,validSave,isLand} from './engine.mjs';
import {CityRenderer,thumbnail} from './city.mjs';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const paths={city:'M3 21h18M5 21V9h6v12M11 21V3h8v18M7 12h2m-2 4h2m4-9h3m-3 4h3m-3 4h3',policy:'M5 3h14v18H5zM8 7h8M8 11h8M8 15h5',chart:'M4 3v18h17M8 16v-4m5 4V8m5 8V5',people:'M16 21v-3a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v3m16 0v-3a4 4 0 0 0-3-3M10 10a3.5 3.5 0 1 0 0-7 3.5 3.5 0 0 0 0 7m7-6a3 3 0 0 1 0 6',restart:'M3 11a9 9 0 1 1 2 7M3 4v7h7',calendar:'M5 4h14a2 2 0 0 1 2 2v14H3V6a2 2 0 0 1 2-2ZM7 2v5m10-5v5M3 10h18M7 14h3m4 0h3m-10 3h3',play:'m9 5 10 7-10 7Z',pause:'M8 5v14m8-14v14',wallet:'M4 6h15V3H5a2 2 0 0 0-2 2v14h18V8H3m18 4h-6v4h6',smile:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20M8 9h.01M16 9h.01M7 14a5 5 0 0 0 10 0',leaf:'M20 3C9 1 2 6 4 14s17 8 16-11ZM5 20 15 9',layers:'m12 3 10 6-10 6L2 9Zm-10 11 10 6 10-6M2 18l10 6 10-6',focus:'M3 9V3h6m6 0h6v6m0 6v6h-6m-6 0H3v-6M9 12h6m-3-3v6',pin:'M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Zm-7 3a3 3 0 1 0 0-6 3 3 0 0 0 0 6',compass:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m4-16-3 7-7 3 3-7Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m0-16v6l4 3',check:'m5 12 4 4L20 5'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.city}"/></svg>`;}
function icons(){$$('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
icons();
const KEY='mandato-aurora-v1';let s=initialState(),saveAvailable=true;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validSave(parsed))s=parsed;}}catch{saveAvailable=false;}
let selected=null,filter='all',view='city',auto=null,toastTimer,renderer;
const fmt=n=>Math.round(n).toLocaleString('pt-BR');
const money=n=>'R$ '+fmt(n)+' mil';
const esc=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=m=>new Date(2027, m,1).toLocaleDateString('pt-BR',{month:'long',year:'numeric'});
const dateLabel=m=>date(m).replace(/^./,c=>c.toUpperCase());
function save(){try{localStorage.setItem(KEY,JSON.stringify(s));saveAvailable=true;}catch{saveAvailable=false;}$('#saved').textContent=saveAvailable?'Salvo neste navegador':'Salvamento indisponível';}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function stopAuto(){clearInterval(auto);auto=null;$('#autoplay').classList.remove('on');$('#autoplay').innerHTML=icon('play');$('#autoplay').setAttribute('aria-label','Ativar avanço automático');$('#autoplay').title='Ativar avanço automático';}
function modal(html){stopAuto();$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
$('#close-modal').onclick=closeModal;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
const effectNames={econ:'economia',green:'preservação',eco:'ambiente',equality:'igualdade',services:'serviços',investment:'empregos',subsidy:'custeio/mês',tax:'tributação'};
function effectTags(e){return Object.entries(e).map(([k,v])=>{if(k==='flag')return `<span class="effect">Desbloqueia ${v==='housing'?'habitação':v==='commerce'?'shopping':'transporte'}</span>`;const text=k==='money'?(v>=0?'+':'−')+' '+money(Math.abs(v)):k==='tax'?(v>0?'+':'−')+' receita por morador':`${v>0?'+':''}${v} ${effectNames[k]||k}`;return `<span class="effect ${k==='money'&&v<0||k==='subsidy'&&v>0?'cost':''}">${text}</span>`;}).join('');}
function renderDecision(){const el=$('#decision-panel');$('#policy-dot').hidden=s.decision===null;
 if(s.ended){el.innerHTML=`<div class="decision-top"><span>${icon('policy')} Fim do mandato</span><small class="pending-badge">RESULTADO</small></div><div class="decision-done"><span>◈</span><h2>${esc(s.election.title)}</h2><p>${esc(s.election.text)}</p><button class="primary" id="show-election" style="margin-top:24px">Ver meu legado →</button></div>`;$('#show-election').onclick=election;return;}
 if(s.decision===null){const h=s.history.at(-1);el.innerHTML=`<div class="decision-top"><span>${icon('check')} Decisão tomada</span><small class="pending-badge">EM VIGOR</small></div><div class="decision-done"><span>✓</span><div class="decision-category">O FUTURO ESTÁ EM MOVIMENTO</div><h2 style="margin-top:12px">${esc(h?.title||'Seu mandato começou')}</h2><p>Sua escolha já está transformando Aurora. Aproveite este momento para construir, acompanhar o orçamento e ouvir a cidade.</p><p class="next-prompt">Próxima pauta em ${dateLabel(s.month+(3-s.month%3))}.<br>Avance o mês para ver as consequências.</p></div>`;return;}
 const p=POLICIES[s.decision];el.innerHTML=`<div class="decision-top"><span>${icon('policy')} Na mesa do prefeito</span><small class="pending-badge">SUA DECISÃO</small></div><div class="decision-content"><div class="decision-category">${p.category}</div><h2>${p.title}</h2><p class="decision-description">${p.body}</p><div class="choices">${p.choices.map((c,i)=>`<button class="choice" data-choice="${i}" ><div class="choice-eyebrow"><i></i>${c.tag}</div><h3>${c.title}</h3><span class="arrow">↗</span><p>${c.body}</p><div class="choice-effects">${effectTags(c.effects)}</div></button>`).join('')}</div><div class="decision-bottom">${icon('clock')} Toda decisão deixa marcas. Os efeitos continuam ao longo do mandato.</div></div>`;
 $$('[data-choice]').forEach(b=>b.onclick=()=>{const err=decide(s,Number(b.dataset.choice));if(err)return toast(err);toast('Política aprovada. Aurora começa a mudar.');render();});}
function renderBuild(){const category={living:['house','tower','social'],economy:['shop','mall','office'],green:['park','forest'],service:['clinic','transit']};$('#build-list').innerHTML=Object.entries(BUILDINGS).filter(([t])=>filter==='all'||category[filter].includes(t)).map(([t,d])=>{const locked=d.unlock&&!d.unlock(s);return `<button class="build-card ${locked?'locked':''} ${selected===t?'selected':''}" data-build="${t}" aria-pressed="${selected===t}" aria-label="${d.name}${locked?'. Requer '+d.requirement:'. '+money(d.cost)}" title="${locked?d.requirement:d.description}">${locked?'<span class="lock-mark">⌑</span>':''}${thumbnail(t)}<strong>${d.short}</strong><small>${locked?'Bloqueado':money(d.cost)}</small></button>`;}).join('');
 $$('[data-build]').forEach(b=>b.onclick=()=>{const t=b.dataset.build,d=BUILDINGS[t];if(d.unlock&&!d.unlock(s))return toast('Para desbloquear: '+d.requirement+'.');if(s.ended)return toast('O mandato terminou. Veja seu legado.');selected=selected===t?null:t;if(view!=='city')setView('city');renderBuild();renderer.selected=selected;renderer.draw();updateInstruction();});
 const el=$('#build-selection');el.hidden=!selected;if(selected){const d=BUILDINGS[selected];el.innerHTML=`<div><strong>${d.name} · ${money(d.cost)}</strong>${d.description}<br>Custeio: ${money(d.maintenance)}/mês. Clique num terreno livre.</div><button class="primary" id="auto-build">Construir automaticamente</button><button class="cancel-build" id="cancel-build" aria-label="Cancelar construção">×</button>`;$('#auto-build').onclick=()=>{for(let y=2;y<=10;y++)for(let x=3;x<=10;x++)if(isLand(x,y)&&!s.buildings.some(b=>b.x===x&&b.y===y)){place(x,y);return;}toast('Todos os terrenos disponíveis já estão ocupados.');};$('#cancel-build').onclick=()=>{selected=null;renderer.selected=null;renderBuild();updateInstruction();renderer.draw();};}}
function updateInstruction(){$('#map-instruction').innerHTML='<span class="live-dot"></span>'+ (selected?'Clique em um terreno livre para construir '+BUILDINGS[selected].short.toLowerCase()+'.':s.decision!==null?'Seu gabinete aguarda uma decisão. A cidade espera por você.':'Construa, acompanhe os indicadores e avance o próximo mês.');}
function place(x,y){if(!selected){const b=s.buildings.find(b=>b.x===x&&b.y===y);if(b){const d=BUILDINGS[b.type];modal(`<div class="modal-label">PATRIMÔNIO DE AURORA</div><div style="width:120px;margin-top:15px">${thumbnail(b.type)}</div><h2 class="modal-title">${d.name}</h2><p class="modal-intro">${d.description}</p><div class="detail-grid"><div class="detail-card"><span>Moradia</span><strong>${fmt(d.housing)}</strong><small>vagas residenciais</small></div><div class="detail-card"><span>Trabalho</span><strong>${d.jobs}</strong><small>postos de trabalho</small></div></div><p class="budget-equation">Custeio municipal: ${money(d.maintenance)} / mês.</p>`);}return;}const err=build(s,selected,x,y);if(err)return toast(err);toast(BUILDINGS[selected].name+' inaugurado!');render();}
function renderDetails(){const el=$('#detail-panel');el.hidden=view==='city';if(view==='city')return;const m=metrics(s);if(view==='budget'){el.innerHTML=`<div class="decision-category">ORÇAMENTO MUNICIPAL</div><h2 style="margin-top:8px">Cada recurso tem um destino.</h2><p>As receitas e os custos abaixo são aplicados ao avançar o mês. Obras e decisões têm efeito imediato no caixa.</p><div class="detail-grid"><div class="detail-card"><span>Receita mensal</span><strong>${money(m.income)}</strong><small>Contribuições de moradores, trabalho e atividade econômica</small></div><div class="detail-card"><span>Despesa mensal</span><strong>${money(m.costs)}</strong><small>Manutenção, serviços e políticas permanentes</small></div><div class="detail-card"><span>Resultado mensal</span><strong style="color:${m.balance<0?'#b67f59':'#618350'}">${m.balance>=0?'+ ':''}${money(m.balance)}</strong><small>${m.balance<0?'Reduza o ritmo de obras e busque novas receitas.':'Espaço para investir no futuro da cidade.'}</small></div><div class="detail-card"><span>Compromissos das políticas</span><strong>${money(s.subsidy)}</strong><small>Parte das despesas que permanece a cada mês</small></div></div><p class="budget-equation">A receita depende da população empregada. Prédios vazios e vagas sem trabalhadores também geram custos.</p>`;}
 if(view==='people'){el.innerHTML=`<div class="decision-category">A CIDADE É FEITA DE GENTE</div><h2 style="margin-top:8px">Diferentes vozes. Uma Aurora.</h2><p>A aprovação pondera famílias (50%), negócios (30%) e ambientalistas (20%). Cada grupo percebe suas decisões de uma forma.</p><div class="detail-grid">${[['Famílias',m.groups.families,'Qualidade de vida, inclusão e moradia'],['Empreendedores',m.groups.business,'Emprego, impostos e liberdade econômica'],['Ambientalistas',m.groups.greens,'Meio ambiente e preservação'],['Igualdade de oportunidades',s.equality,'Quanto maior, mais inclusiva é a cidade']].map(([name,val,text])=>`<div class="detail-card"><span>${name}</span><strong>${fmt(val)}<small> / 100</small></strong><small>${text}</small><div class="metric-bar"><i style="width:${val}%"></i></div></div>`).join('')}</div><p class="budget-equation">Emprego: ${fmt(m.employment)}% · Qualidade de vida: ${fmt(m.quality)}/100 · Capacidade habitacional: ${fmt(m.housing)}</p>`;}
 if(view==='policies'){el.innerHTML=`<div class="decision-category">O RUMO QUE VOCÊ ESCOLHEU</div><h2 style="margin-top:8px">Seu legado, decisão por decisão.</h2><p>As políticas ficam em vigor. A orientação econômica e ambiental acumula suas escolhas ao longo do tempo.</p>${s.history.length?s.history.slice().reverse().map(h=>`<article class="history-item"><small>${dateLabel(h.month)}</small><h3>${esc(h.title)}</h3><p>Economia: ${h.econ} · Preservação: ${h.green}</p></article>`).join(''):'<p class="empty-history">Seu primeiro capítulo ainda está em branco. Escolha uma proposta na mesa do prefeito para começar.</p>'}`;}}
function setView(v){view=v;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#map-title').textContent={city:'A cidade acontece aqui',policies:'As escolhas que ficam',budget:'O caixa da cidade',people:'Quem faz Aurora'}[v];renderDetails();}
function render(){const m=metrics(s);$('#money').innerHTML=`R$ ${fmt(s.money)} <small>mil</small>`;$('#population').textContent=fmt(s.pop);$('#approval').innerHTML=`${fmt(m.approval)}<small>%</small>`;$('#environment').innerHTML=`${fmt(s.eco)}<small>/100</small>`;$('#balance').textContent=`${m.balance>=0?'+ ':'− '}${money(Math.abs(m.balance))} / mês`;$('#balance').className='stat-foot'+(m.balance<0?' negative':'');$('#housing').textContent=`${fmt(m.housing-s.pop)} vagas residenciais livres`;$('#approval-label').textContent=m.approval>=65?'A cidade está com você':m.approval>=50?'Apoio com espaço para crescer':'A cidade pede uma mudança';$('#approval-label').className='stat-foot'+(m.approval<50?' negative':'');$('#environment-label').textContent=s.eco>=65?'Respirando novos ares':s.eco>=40?'O verde precisa de atenção':'O ambiente pede socorro';$('#environment-label').className='stat-foot'+(s.eco<40?' negative':'');$('#month').textContent=dateLabel(s.month);$('#term-progress').textContent=`Mês ${s.ended?48:s.month%48+1} de 48`;$('#term-label').textContent=`${s.term}º mandato`;$('#actions').textContent=`${s.actions} obra${s.actions===1?'':'s'} disponíve${s.actions===1?'l':'is'}`;$('#building-count').textContent=`${s.buildings.length} construções`;$('#city-identity').textContent=`Uma cidade ${identity(s).toLowerCase()}`;$('#econ-marker').style.left=(s.econ+100)/2+'%';$('#green-marker').style.left=(s.green+100)/2+'%';$('#economy-type').textContent=s.econ< -15?'Solidária':s.econ>15?'De mercado':'Equilibrada';$('#green-type').textContent=s.green< -15?'Expansionista':s.green>15?'Preservacionista':'Equilibrado';$('#identity-note').textContent=s.history.length?`${s.history.length} decisões construíram uma Aurora ${identity(s).toLowerCase()}.`:'O caminho se revela a cada decisão.';$('#city-level').innerHTML=s.pop>=4000?'CIDADE REGIONAL <i>● ● ● ●</i>':s.pop>=2400?'CIDADE EM EXPANSÃO <i>● ● ● ○</i>':'PEQUENA CIDADE <i>● ● ○ ○</i>';$('#next-month').disabled=s.ended;$('#autoplay').disabled=s.ended;
 $('#journal-text').textContent=s.lastEvent?'“'+s.lastEvent.title+'.”':s.month===0?'“Toda cidade começa com uma ideia. A nossa começa com você.”':s.eco<45?'“O bairro cresceu. A sombra das árvores faz falta.”':s.equality<40?'“Tem muita coisa nova por aqui. Mas será que é para todo mundo?”':m.employment<75?'“Quero ficar em Aurora. Só falta uma oportunidade de trabalho.”':s.econ>20?'“Abri meu negócio. Agora quero ver o bairro inteiro prosperar.”':s.econ< -20?'“Pela primeira vez, sinto que a cidade também cuida da gente.”':'“É bom ver nossa cidade encontrando seu próprio caminho.”';
 renderDecision();renderBuild();renderDetails();updateInstruction();if(renderer){renderer.selected=selected;renderer.draw();}save();}
function next(){const err=advance(s);if(err){stopAuto();toast(err);$('#decision-panel').scrollIntoView({behavior:'smooth',block:'nearest'});return;}render();if(s.lastEvent)toast(s.lastEvent.title+' · '+s.lastEvent.text);if(s.ended){stopAuto();election();}else if(s.decision!==null){stopAuto();toast('Uma nova decisão chegou ao seu gabinete.');}}
function election(){const m=metrics(s);modal(`<div class="modal-label">${s.term}º MANDATO · SEU LEGADO</div><h2 class="modal-title">${esc(s.election.title)}</h2><div class="election-score">${fmt(m.approval)}<small>% de apoio</small></div><p class="modal-intro">${esc(s.election.text)}</p><div class="detail-grid"><div class="detail-card"><span>População</span><strong>${fmt(s.pop)}</strong></div><div class="detail-card"><span>Cidade construída</span><strong>${identity(s)}</strong></div></div><div class="modal-actions"><button class="secondary" id="election-restart">Nova cidade</button>${s.election.won?'<button class="primary" id="continue-term">Iniciar novo mandato →</button>':''}</div>`);$('#election-restart').onclick=resetPrompt;if(s.election.won)$('#continue-term').onclick=()=>{continueTerm(s);closeModal();render();};}
function resetPrompt(){modal('<div class="modal-label">UM NOVO COMEÇO</div><h2 class="modal-title">Outra cidade. Outras escolhas.</h2><p class="modal-intro">Começar de novo substitui o progresso de Aurora salvo neste navegador. Você volta ao primeiro mês, com R$ 850 mil em caixa.</p><div class="modal-actions"><button class="secondary" id="cancel-reset">Continuar esta cidade</button><button class="primary" id="confirm-reset">Começar nova cidade →</button></div>');$('#cancel-reset').onclick=closeModal;$('#confirm-reset').onclick=()=>{s=initialState();selected=null;filter='all';$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter==='all');b.setAttribute('aria-selected',String(b.dataset.filter==='all'));});setView('city');renderer.zoom=1;closeModal();render();toast('Bem-vindo a uma nova Aurora.');};}
function help(){modal(`<div class="modal-label">BEM-VINDO AO GABINETE</div><h2 class="modal-title">Que cidade você quer construir?</h2><p class="modal-intro">Você tem quatro anos para dar forma a Aurora. Não há uma ideologia vencedora por definição: os resultados dependem de como você equilibra suas escolhas.</p><div class="modal-items"><article><h3>01 · Escolha um rumo</h3><p>A cada três meses, uma pauta chega à mesa. Leia os efeitos, escolha uma política e veja sua orientação econômica e ambiental mudar.</p></article><article><h3>02 · Dê forma à cidade</h3><p>Selecione uma construção e clique num terreno livre. Você também pode usar “Construir automaticamente”. São até três obras por mês. Prédios, shoppings e habitação social têm condições para desbloquear.</p></article><article><h3>03 · Deixe o tempo passar</h3><p>“Próximo mês” aplica receitas, despesas, migração e consequências. O botão de reprodução avança a cada seis segundos e pausa quando você precisa decidir.</p></article><article><h3>04 · Conquiste um novo mandato</h3><p>Ao final de 48 meses, 50% de aprovação garantem a reeleição. Políticas podem gerar déficit; obras exigem saldo. Um caixa abaixo de −R$ 160 mil provoca intervenção ao fechar o mês. Famílias, empresas e ambientalistas influenciam seu apoio.</p></article></div><p class="modal-intro" style="font-size:10px">Aurora é fictícia e seus efeitos são regras de jogo, não previsões de políticas reais. O progresso é salvo automaticamente neste navegador.</p><div class="modal-actions"><button class="primary" id="start-playing">Vamos governar →</button></div>`);$('#start-playing').onclick=closeModal;}
$('#help').onclick=help;$('#mayor').onclick=()=>{setView('policies');$('#detail-panel').scrollIntoView({behavior:'smooth',block:'nearest'});};$('#new-game').onclick=resetPrompt;$('#next-month').onclick=next;$('#autoplay').onclick=()=>{if(auto)return stopAuto();if(s.decision!==null)return toast('Primeiro, responda à pauta na mesa do prefeito.');auto=setInterval(next,6000);$('#autoplay').classList.add('on');$('#autoplay').innerHTML=icon('pause');$('#autoplay').setAttribute('aria-label','Pausar avanço automático');$('#autoplay').title='Pausar avanço automático';toast('O tempo está passando. Um mês a cada 6 segundos.');};
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$$('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;$$('[data-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-selected',String(t===b));});renderBuild();});
$('#open-history').onclick=()=>modal(`<div class="modal-label">DIÁRIO DA CIDADE</div><h2 class="modal-title">Aurora tem histórias.</h2><p class="modal-intro">Decisões, obras e acontecimentos que marcaram seu mandato.</p>${s.log.map(l=>`<article class="history-item"><small>${dateLabel(l.month)}</small><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></article>`).join('')}`);
renderer=new CityRenderer($('#city'),()=>s,place);$('#zoom-in').onclick=()=>{renderer.zoom=Math.min(1.6,renderer.zoom+.15);renderer.draw();};$('#zoom-out').onclick=()=>{renderer.zoom=Math.max(.7,renderer.zoom-.15);renderer.draw();};$('#zoom-reset').onclick=()=>{renderer.zoom=1;renderer.draw();};$('#map-mode').onclick=()=>{if(view!=='city')setView('city');renderer.layer=(renderer.layer+1)%2;$('#map-mode-label').textContent=renderer.layer?'Uso do solo':'Visão da cidade';renderer.draw();};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAuto();});window.addEventListener('pagehide',save);render();if(s.ended)election();
